import itertools

def solve(n):
    num_subsets = 1 << n
    subsets = []
    for i in range(num_subsets):
        subset = set()
        for j in range(n):
            if (i >> j) & 1:
                subset.add(j)
        subsets.append(subset)

    # To speed up, precalculate subset relationships
    # is_subset[i][j] = True if subsets[i] is a subset of subsets[j]
    is_subset = [[False] * num_subsets for _ in range(num_subsets)]
    for i in range(num_subsets):
        for j in range(num_subsets):
            if subsets[i].issubset(subsets[j]):
                is_subset[i][j] = True

    # union_idx[i][j] = index of subsets[i] | subsets[j]
    # intersection_idx[i][j] = index of subsets[i] & subsets[j]
    union_idx = [[0] * num_subsets for _ in range(num_subsets)]
    intersection_idx = [[0] * num_subsets for _ in range(num_subsets)]
    for i in range(num_subsets):
        for j in range(num_subsets):
            u = subsets[i] | subsets[j]
            inter = subsets[i] & subsets[j]
            # find the index of u and inter
            # Since subsets are generated in order, we can find them easily
            # The index of a subset is the integer representing its bitmask
            u_idx = 0
            for x in u:
                u_idx |= (1 << x)
            inter_idx = 0
            for x in inter:
                inter_idx |= (1 << x)
            union_idx[i][j] = u_idx
            intersection_idx[i][j] = inter_idx

    count = 0
    for coloring in itertools.product([0, 1], repeat=num_subsets):
        # Precompute f(T) for this coloring
        f = [0] * num_subsets
        for i in range(num_subsets):
            for j in range(num_subsets):
                if is_subset[j][i]:
                    f[i] += coloring[j]

        valid = True
        for i in range(num_subsets):
            for j in range(i + 1, num_subsets):
                if f[i] * f[j] != f[union_idx[i][j]] * f[intersection_idx[i][j]]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            count += 1
    return count

for n in range(1, 5):
    print(f"n={n}, count={solve(n)}")
